        internal Fixture(bool auto=false){Directory.CreateDirectory(Path.Combine(DirectoryPath,"credentials"));Directory.CreateDirectory(Path.Combine(DirectoryPath,"keys"));Protection=DataProtectionProvider.Create(new DirectoryInfo(Path.Combine(DirectoryPath,"keys")));using(var legacy=new SqliteConnection(new SqliteConnectionStringBuilder{DataSource=Path.Combine(DirectoryPath,"test.db"),Pooling=false}.ToString())){legacy.Open();using var command=legacy.CreateCommand();command.CommandText="CREATE TABLE CskhChannelOutbox(Id TEXT PRIMARY KEY,Conversation TEXT NOT NULL,Message TEXT NOT NULL UNIQUE,Connection TEXT NOT NULL,Binding TEXT NOT NULL,Peer TEXT NOT NULL,Reference TEXT NOT NULL,Kind TEXT NOT NULL,Actor INTEGER,State TEXT NOT NULL,Job TEXT,ExternalId TEXT,Code TEXT,Attempts INTEGER NOT NULL DEFAULT 0,Available INTEGER NOT NULL,Created INTEGER NOT NULL,Updated INTEGER NOT NULL); PRAGMA user_version=8;";command.ExecuteNonQuery();}File.WriteAllText(Path.Combine(DirectoryPath,"credentials","token"),"SYNTHETIC_BEARER_TOKEN_ONLY");using var rsa=RSA.Create(2048);File.WriteAllText(Path.Combine(DirectoryPath,"key.pem"),rsa.ExportRSAPrivateKeyPem());
