        private async Task<HttpResponseMessage> Handle(HttpRequestMessage r){object result;var path=r.RequestUri!.AbsolutePath;
            if(path=="/api/customer/v1/messages"){AiCalls++;var body=await r.Content!.ReadFromJsonAsync<JsonElement>();if(AfterAiResponse is not null){var action=AfterAiResponse;AfterAiResponse=null;await action();}return CustomerChannelTransportTests.Json(new{contractVersion="1.0",requestId=body.GetProperty("requestId").GetGuid(),conversationId=body.GetProperty("conversationId").GetGuid(),scope=new{storeId="1",warehouseId=(string?)null,legalEntityId=(string?)null},reply="TEST AI verified response",state=new{conversationId=body.GetProperty("conversationId").GetGuid(),recentMessages=Array.Empty<object>()}});}
            Assert.Equal("Bearer SYNTHETIC_BEARER_TOKEN_ONLY",r.Headers.Authorization!.ToString());
            if(InboxSource is not null&&r.Method==HttpMethod.Get&&path.StartsWith("/api/v1/inbox/conversations")){var supplied=InboxSource(r);supplied.Headers.Add("X-ZaloMarketing-Sender-Profile-Id",WrongProfile?Guid.NewGuid().ToString():Connection.AccountId);return supplied;}
            if(path=="/api/v1/inbox/conversations")result=new{sync=new{enabled=true,status="Ready"},conversations=new[]{new{id=Peer,conversationKind=ConversationKind}},hasNextPage=false};
            else if(path==$"/api/v1/inbox/conversations/{Peer:D}") {var messages=new List<object>{new{sequence=1,text="OLD baseline text",kind="Text",observedAtUtc=Clock.Now.AddHours(-1),isOutgoing=false}};if(Fresh)messages.Add(new{sequence=2,text="TEST sữa tươi",kind=MessageKind,observedAtUtc=Clock.Now,isOutgoing=false,senderName="TEST Thành viên <img src=x>",quotedText="TEST trích dẫn",attachments=WithMedia?new[]{new{id=MediaId,kind=MessageKind=="Image"?"Image":"File",fileName=MessageKind=="Image"?"anh.png":"bao-gia.pdf",contentType=MessageKind=="Image"?"image/png":"application/pdf",length=100L}}:Array.Empty<object>()});if(Backfill)messages.Insert(1,new{sequence=3,text="OLD restored text",kind="Text",observedAtUtc=Clock.Now,isOutgoing=false});result=new{id=Peer,displayName="TEST same name",kind=ConversationKind,hasOlder=false,messages};}
            else if(path.EndsWith("/replies")){Sends++;Posts.Add((r.Headers.GetValues("Idempotency-Key").Single(),await r.Content!.ReadAsStringAsync()));if(LoseFirstAcknowledgement&&Sends==1)throw new HttpRequestException("TEST lost acknowledgement");result=new{jobId=Job,conversationId=Peer,replyToSequence=JsonDocument.Parse(Posts[^1].Body).RootElement.GetProperty("replyToSequence").GetInt64(),status="Pending",idempotencyReplayed=Sends>1};}
            else if(path==$"/api/v1/jobs/{Job:D}")result=new{jobId=Job,senderProfileId=Guid.Parse(Connection.AccountId),status="Completed",summary=new{total=1,sent=1,needsReview=0,partiallySent=0,failed=0,notFound=0,skipped=0}};
            else throw new InvalidOperationException("Unexpected synthetic request: "+path);
            var response=CustomerChannelTransportTests.Json(result);response.Headers.Add("X-ZaloMarketing-Sender-Profile-Id",WrongProfile?Guid.NewGuid().ToString():Connection.AccountId);return response;
        }
        internal async Task Receive(){await Runner.Run(Connection.Id,true,default);Assert.Empty(Store.Inbox(Agent,"all"));Clock.Now=Clock.Now.AddMinutes(1);Fresh=true;await Runner.Run(Connection.Id,true,default);}
        internal async Task QueueAiReplyForFinalFence(){await Runner.Run(Connection.Id,true,default);Clock.Now=Clock.Now.AddMinutes(1);var imported=Store.ImportChannel(Connection,new("TEST final-fence-event",Peer.ToString(),"TEST sữa tươi",Clock.Now,"2"));Assert.NotNull(imported);var turn=Store.TakeChannelTurn(Connection)!;var policy=await Policies.ReadAsync(1,default);var settings=await Switches.ReadAsync(1,default);Store.Complete(turn.Who,"TEST queued AI response","{}",null,policy.Version,settings.Version);}
        internal Guid Reply(){var row=Assert.Single(Store.Inbox(Agent,"all"));row=Store.StaffCommand(Agent,row.Id,new(Guid.NewGuid(),"claim",row.Version));Store.StaffCommand(Agent,row.Id,new(Guid.NewGuid(),"reply",row.Version,"TEST staff reply"));return row.Id;}
        public async ValueTask DisposeAsync(){http.Dispose();await Db.DisposeAsync();if(Directory.Exists(DirectoryPath))Directory.Delete(DirectoryPath,true);}
