    private class RewardStub:DispatchProxy
    {
        internal bool FailReads{get;set;}
        protected override object Invoke(MethodInfo? method,object?[]? args){if(FailReads&&method?.Name is nameof(ICustomerRewardService.IsProgramEnabledAsync) or nameof(ICustomerRewardService.GetBalanceAsync) or nameof(ICustomerRewardService.GetAvailableVouchersAsync))throw new InvalidOperationException("TEST reward source unavailable");return method?.Name switch {
            nameof(ICustomerRewardService.IsProgramEnabledAsync)=>Task.FromResult(true),
            nameof(ICustomerRewardService.GetBalanceAsync)=>Task.FromResult(new CustomerRewardBalanceDto{CustomerId=42,IsPointEligible=true,BalanceAmount=1500m,MoneyPerPoint=100m,PointsPerVoucher=5,VoucherValue=2000m}),
            nameof(ICustomerRewardService.GetAvailableVouchersAsync)=>Task.FromResult(new List<CustomerRewardVoucherDto>{new(){Id=7,VoucherCode="TEST-VOUCHER-42",Value=2000m,Status="Available",IssuedAtUtc=DateTime.UtcNow}}),
            _=>throw new NotSupportedException("Unexpected reward API in test: "+method?.Name)
        };}
        internal static ICustomerRewardService Create(bool failReads=false){var proxy=DispatchProxy.Create<ICustomerRewardService,RewardStub>();((RewardStub)(object)proxy).FailReads=failReads;return proxy;}
    }
    private static async Task<(CustomerConversation Row,CustomerIdentityCode Code)> IssueCustomerIdentity(Fixture f){
        await f.Receive();f.Db.Customers.Add(new Customer{Id=42,StoreId=1,Name="TEST customer",Phone="0398946174",IsActive=true,IsDeleted=false});
        f.Db.AddRange(
            new LegalEntity{Id=11,StoreId=1,Code="TEST-LEGAL",Name="TEST legal",LegalName="TEST legal"},
            new Warehouse{Id=11,StoreId=1,LegalEntityId=11,Code="TEST-WAREHOUSE",Name="TEST warehouse"},
            new POSTerminal{Id=11,StoreId=1,Code="TEST-POS",Name="TEST terminal"},
            new POSShift{Id=11,StoreId=1,TerminalId=11,WarehouseId=11,OpenedByUserId=1,OpenedAtUtc=f.Clock.Now.UtcDateTime});
        f.Db.Orders.Add(new Order{Id=501,StoreId=1,POSShiftId=11,CustomerId=42,OrderNumber="TEST-ORDER-501",Status=GaoApp.Domain.Enums.OrderStatus.Completed,PaymentStatus=GaoApp.Domain.Enums.PaymentStatus.Paid,CompletedAtUtc=f.Clock.Now.UtcDateTime,GrandTotal=125000,IsDeleted=false});await f.Db.SaveChangesAsync();
        var row=Assert.Single(f.Store.Inbox(f.Agent,"all"));row=f.Store.StaffCommand(f.Agent,row.Id,new(Guid.NewGuid(),"claim",row.Version));
        var business=new CustomerBusinessRead(f.Db,f.Store,f.Access,f.Rewards,f.Protection,f.Clock);var code=await business.Issue(f.Agent,row.Id,new(Guid.NewGuid(),row.Version,42,"verified_callback","TEST callback verified",true),default);
        return(row,code);
    }
    private static async Task<CustomerConversation> VerifiedCustomer(Fixture f){var issued=await IssueCustomerIdentity(f);Assert.True(f.Store.RedeemIdentity(1,issued.Row.VisitorId,issued.Row.Id,new(Guid.NewGuid(),issued.Code.Code!)));f.Connection.AutoReply=true;return issued.Row;}
    [Fact]public async Task Zalo_baseline_new_text_staff_reply_and_job_reconciliation_work_without_real_send(){await using var f=new Fixture();await f.Receive();var id=f.Reply();await f.Runner.Run(f.Connection.Id,false,default);Assert.Equal(1,f.Sends);Assert.Equal("accepted",f.Store.StaffGet(f.Agent,id).Messages.Single(m=>m.Role=="agent").Delivery!.State);f.Clock.Now=f.Clock.Now.AddSeconds(16);await f.Runner.Run(f.Connection.Id,false,default);Assert.Equal("sent",f.Store.StaffGet(f.Agent,id).Messages.Single(m=>m.Role=="agent").Delivery!.State);Assert.Equal(1,f.Sends);Assert.Equal(0,f.AiCalls);}
    [Fact]public async Task Verified_private_order_query_reads_GaoApp_and_never_calls_the_AI_bridge(){await using var f=new Fixture();var row=await VerifiedCustomer(f);var imported=f.Store.ImportChannel(f.Connection,new("TEST private order event",f.Peer.ToString(),"đơn hàng của tôi",f.Clock.Now,"2"));Assert.Equal(row.Id,imported);await f.Runner.Run(f.Connection.Id,false,default);Assert.Equal(0,f.AiCalls);Assert.Equal(1,f.Sends);using var sent=JsonDocument.Parse(f.Posts.Single().Body);var reply=sent.RootElement.GetProperty("text").GetString()!;Assert.Contains("TEST-ORDER-501",reply);Assert.Contains("125.000",reply);var transcript=f.Store.StaffGet(f.Agent,row.Id).Messages;Assert.DoesNotContain(transcript,m=>m.Text.Contains("TEST-ORDER-501",StringComparison.Ordinal));Assert.DoesNotContain(transcript,m=>m.Text.Contains("125.000",StringComparison.Ordinal));}
    [Fact]public async Task Verified_private_reward_query_distinguishes_points_redeemable_vouchers_and_issued_vouchers(){await using var f=new Fixture();var row=await VerifiedCustomer(f);f.Store.ImportChannel(f.Connection,new("TEST private rewards event",f.Peer.ToString(),"tôi có bao nhiêu điểm và voucher của tôi",f.Clock.Now,"2"));var turn=f.Store.TakeChannelPrivateTurn(f.Connection);Assert.NotNull(turn);var business=new CustomerBusinessRead(f.Db,f.Store,f.Access,f.Rewards,f.Protection,f.Clock);var generated=await business.ChannelReply(f.Connection,turn!,default);Assert.NotNull(generated);Assert.Contains("1.500",generated!.Value.Reply);Assert.Contains("15",generated.Value.Reply);Assert.Contains("3",generated.Value.Reply);Assert.Contains("TEST-VOUCHER-42",generated.Value.Reply);f.Store.CompleteChannelPrivateTurn(turn!,generated.Value.Reply,generated.Value.Generation);await f.Runner.Run(f.Connection.Id,false,default);Assert.Equal(0,f.AiCalls);Assert.Equal(1,f.Sends);Assert.DoesNotContain(f.Store.StaffGet(f.Agent,row.Id).Messages,m=>m.Text.Contains("TEST-VOUCHER-42",StringComparison.Ordinal));}
    [Fact]public async Task Reward_source_errors_are_reported_as_unavailable_and_never_as_zero(){await using var f=new Fixture();var row=await VerifiedCustomer(f);var business=new CustomerBusinessRead(f.Db,f.Store,f.Access,RewardStub.Create(failReads:true),f.Protection,f.Clock);var result=await business.Rewards(1,row.VisitorId,row.Id,default);using var json=JsonDocument.Parse(JsonSerializer.Serialize(result));var reward=json.RootElement.GetProperty("reward");Assert.Equal("unavailable",reward.GetProperty("status").GetString());Assert.False(reward.TryGetProperty("points",out _));Assert.False(reward.TryGetProperty("redeemableVoucherCount",out _));}
    [Fact]public async Task Changing_customer_phone_after_private_read_cancels_dispatch_and_revokes_the_grant(){await using var f=new Fixture();var row=await VerifiedCustomer(f);f.Store.ImportChannel(f.Connection,new("TEST private phone event",f.Peer.ToString(),"đơn hàng của tôi",f.Clock.Now,"2"));var turn=f.Store.TakeChannelPrivateTurn(f.Connection);Assert.NotNull(turn);var business=new CustomerBusinessRead(f.Db,f.Store,f.Access,f.Rewards,f.Protection,f.Clock);var result=await business.ChannelReply(f.Connection,turn!,default);Assert.NotNull(result);f.Store.CompleteChannelPrivateTurn(turn!,result!.Value.Reply,result.Value.Generation);var customer=await f.Db.Customers.SingleAsync(c=>c.Id==42);customer.Phone="0312345678";await f.Db.SaveChangesAsync();await f.Runner.Run(f.Connection.Id,false,default);Assert.Equal(0,f.Sends);Assert.Equal("cancelled",f.Store.StaffGet(f.Agent,row.Id).Messages.Single(m=>m.Text=="Đã gửi thông tin riêng đã xác minh qua kênh.").Delivery!.State);Assert.Throws<AssistantException>(()=>f.Store.RequireIdentity(1,row.VisitorId,row.Id));}
    [Fact]public async Task Changing_customer_phone_before_code_redemption_invalidates_the_pending_code(){await using var f=new Fixture();var issued=await IssueCustomerIdentity(f);f.Connection.AutoReply=true;var customer=await f.Db.Customers.SingleAsync(c=>c.Id==42);customer.Phone="0312345678";await f.Db.SaveChangesAsync();f.Store.ImportChannel(f.Connection,new("TEST stale identity code",f.Peer.ToString(),issued.Code.Code!,f.Clock.Now,"2"));await f.Runner.Run(f.Connection.Id,false,default);Assert.Equal(0,f.AiCalls);Assert.Equal(1,f.Sends);using var sent=JsonDocument.Parse(f.Posts.Single().Body);Assert.Contains("đã thay đổi",sent.RootElement.GetProperty("text").GetString());Assert.Throws<AssistantException>(()=>f.Store.PendingIdentity(1,issued.Row.VisitorId,issued.Row.Id));Assert.Throws<AssistantException>(()=>f.Store.RequireIdentity(1,issued.Row.VisitorId,issued.Row.Id));}
    [Fact]public async Task Zalo_lost_acknowledgement_retries_same_frozen_request_only(){await using var f=new Fixture();await f.Receive();f.Reply();f.LoseFirstAcknowledgement=true;await f.Runner.Run(f.Connection.Id,false,default);f.Clock.Now=f.Clock.Now.AddSeconds(16);await f.Runner.Run(f.Connection.Id,false,default);Assert.Equal(2,f.Sends);Assert.Equal(f.Posts[0],f.Posts[1]);}
