    [Fact]public async Task Policy_changed_during_AI_turn_hands_off_without_queueing_stale_answer(){await using var f=new Fixture(true);f.AfterAiResponse=async()=>await f.Policies.SaveAsync(1,1,new("delivery","TEST policy","TEST draft policy",f.Clock.Now,null,"TEST"),Guid.Empty.ToString("N"),Guid.NewGuid(),default);await f.Receive();var row=Assert.Single(f.Store.Inbox(f.Agent,"all"));Assert.Equal("waiting",row.Mode);Assert.DoesNotContain(f.Store.StaffGet(f.Agent,row.Id).Messages,m=>m.Text=="TEST AI verified response");}
